import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useLocation, useNavigate } from 'react-router-dom';

// --- NAVBAR ---
const Navbar = ({ cartCount }) => {
  const user = localStorage.getItem('username');
  const handleLogout = () => { localStorage.clear(); window.location.href = "/login"; };

  return (
    <nav className="bg-white/95 backdrop-blur-md sticky top-0 z-50 w-full border-b border-gray-100 shadow-sm">
      <div className="max-w-7xl mx-auto px-6 h-20 flex justify-between items-center">
        <Link to="/" className="font-black text-xl tracking-tighter text-gray-900 uppercase italic">
          Fast<span className="text-orange-600">Délice</span>
        </Link>
        <div className="flex items-center space-x-6">
          <Link to="/" className="text-[12px] font-black uppercase hover:text-orange-600">Accueil</Link>
          <Link to="/menu" className="text-[12px] font-black uppercase hover:text-orange-600">Menu</Link>
          {user ? (
            <div className="flex items-center space-x-4">
              <span className="text-[11px] font-black text-orange-600 uppercase italic">Salut, {user}</span>
              <button onClick={handleLogout} className="text-red-600 text-[10px] font-black uppercase">Quitter</button>
            </div>
          ) : (
            <Link to="/login" className="bg-orange-600 text-white px-5 py-2 rounded-full text-[11px] font-black uppercase shadow-lg">Connexion</Link>
          )}
        </div>
      </div>
    </nav>
  );
};

// --- HOME (M3A LES COMMENTAIRES FL-TE7T) ---
const Home = () => (
  <div>
    {/* Hero Section */}
    <div className="relative h-[80vh] flex items-center justify-center overflow-hidden">
      <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="absolute inset-0 w-full h-full object-cover" alt="pizza" />
      <div className="absolute inset-0 bg-black/50"></div>
      <div className="relative z-10 text-center text-white px-6">
        <h1 className="text-7xl md:text-9xl font-black italic tracking-tighter mb-4">Fast<span className="text-orange-600">Délice</span></h1>
        <p className="text-xl italic font-bold mb-8">"La passion du goût, l'élégance du service."</p>
        <Link to="/menu" className="bg-orange-600 text-white px-12 py-4 rounded-full font-black uppercase tracking-widest hover:bg-white hover:text-orange-600 transition shadow-2xl">Commander Maintenant</Link>
      </div>
    </div>

    {/* Section: Ce que nos clients disent */}
    <div className="bg-white py-24 px-6">
      <div className="max-w-7xl mx-auto text-center">
        <h2 className="text-3xl font-black italic uppercase tracking-tighter mb-16 text-gray-900">Ce que nos clients disent</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {[
            { n: "SARAH B.", t: "La meilleure pizza que j'ai mangée à Fès!", s: "★★★★★" },
            { n: "AHMED L.", t: "Livraison rapide et plats chauds. Top!", s: "★★★★★" },
            { n: "YOUSSEF M.", t: "Qualité exceptionnelle pour le prix.", s: "★★★★" }
          ].map((v, i) => (
            <div key={i} className="bg-gray-50/50 p-10 rounded-3xl border border-gray-100 shadow-sm hover:shadow-md transition">
              <div className="text-orange-500 mb-4 text-xs tracking-widest">{v.s}</div>
              <p className="text-gray-700 italic font-medium mb-6">"{v.t}"</p>
              <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">— {v.n}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  </div>
);

// --- LOGIN (L-Logic west l-form) ---
const Login = () => {
  const [formData, setFormData] = useState({ username: '', password: '' });
  const [error, setError] = useState("");

  const handleLogin = async (e) => {
    e.preventDefault();
    setError("");
    try {
      const res = await axios.post('http://127.0.0.1:8000/api/login/', formData);
      localStorage.setItem('username', res.data.username || "KAWTHAR");
      window.location.href = "/";
    } catch (err) {
      setError("❌ Identifiants incorrects.");
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-900 px-6 relative">
      <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591" className="absolute inset-0 w-full h-full object-cover opacity-30" alt="bg" />
      <div className="max-w-md w-full bg-black/40 backdrop-blur-xl border border-white/10 p-10 rounded-[3rem] shadow-2xl relative z-10 text-center">
        <h2 className="text-white text-5xl font-black italic uppercase mb-8 tracking-tighter">Connexion</h2>
        <div className="h-1 w-12 bg-orange-600 mx-auto mb-8"></div>

        {/* Message Error west l-form */}
        {error && <p className="mb-6 text-red-400 font-bold text-sm italic">{error}</p>}

        <form className="space-y-6" onSubmit={handleLogin}>
          <input type="text" placeholder="VOTRE EMAIL" required className="w-full bg-white/10 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" 
            onChange={(e) => setFormData({...formData, username: e.target.value})} />
          <input type="password" placeholder="MOT DE PASSE" required className="w-full bg-white/10 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" 
            onChange={(e) => setFormData({...formData, password: e.target.value})} />
          <button type="submit" className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-orange-600 transition shadow-lg">Se Connecter</button>
        </form>
      </div>
    </div>
  );
};

export default function App() {
  return (
    <Router>
      <div className="min-h-screen">
        <Navbar cartCount={0} />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/login" element={<Login />} />
        </Routes>
      </div>
    </Router>
  );
}
